      needed.hashCode ^
      txid.hashCode ^
      error.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SendProgress &&
          runtimeType == other.runtimeType &&
          stage == other.stage &&
          received == other.received &&
          needed == other.needed &&
          txid == other.txid &&
          error == other.error;
}

enum SendStage { collecting, sent, failed }
